"""Spring Boot, generated by the real Spring Initializr service."""

from __future__ import annotations

from urllib.parse import urlencode

from launchpad.scaffold import files
from launchpad.scaffold.files import TaskSpec
from launchpad.scaffold.plan import Download, FileSpec, Step

INITIALIZR_URL = "https://start.spring.io/starter.zip"
SPRING_PORT = 8080
GROUP_ID = "com.surge"
# h2 keeps `mvn test` runnable on a clean machine: the generated context test
# would otherwise demand a live Postgres, and a scaffold whose own tests fail is
# a broken scaffold.
DEPENDENCIES = "web,data-jpa,postgresql,validation,actuator,h2"


def initializr_url(name: str) -> str:
    """Ask start.spring.io for the same zip its web UI produces."""
    query = urlencode(
        {
            "type": "maven-project",
            "language": "java",
            "javaVersion": "21",
            "groupId": GROUP_ID,
            "artifactId": name,
            "name": name,
            "packageName": f"{GROUP_ID}.{_package_suffix(name)}",
            "description": f"{name} service",
            "dependencies": DEPENDENCIES,
        }
    )
    return f"{INITIALIZR_URL}?{query}"


def _package_suffix(name: str) -> str:
    """Java packages allow neither dashes nor a leading digit."""
    cleaned = "".join(char if char.isalnum() else "" for char in name.lower())
    return f"app{cleaned}" if not cleaned or cleaned[0].isdigit() else cleaned


def spring_boot(name: str) -> list[Step]:
    return [
        Download(label="fetch Spring Initializr project", url=initializr_url(name)),
        _application_properties(name),
        _test_properties(),
        files.postgres_compose(name),
        files.env_example(
            {
                "POSTGRES_URL": f"jdbc:postgresql://localhost:5432/{name}",
                "POSTGRES_USER": name,
                "POSTGRES_PASSWORD": name,
            }
        ),
        files.launcher_toml(
            [TaskSpec(name="api", cmd="mvn spring-boot:run", port=SPRING_PORT)]
        ),
        files.readme(
            name,
            "Spring Boot 3 (Java 21) + JPA + Postgres",
            [
                "`docker compose up -d` to start Postgres",
                "`mvn spring-boot:run`",
                "Check `http://localhost:8080/actuator/health`",
            ],
            [
                "Generated by the real Spring Initializr, so the layout matches start.spring.io exactly.",
                "Datasource values come from environment variables with local defaults baked in.",
                "`mvn test` runs the generated context-loads test.",
            ],
        ),
    ]


def _test_properties() -> FileSpec:
    """Tests run against in-memory H2, so `mvn test` needs no Docker or Postgres."""
    return FileSpec(
        path="src/test/resources/application.properties",
        content="""spring.datasource.url=jdbc:h2:mem:testdb;DB_CLOSE_DELAY=-1;MODE=PostgreSQL
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

spring.jpa.hibernate.ddl-auto=create-drop
spring.jpa.database-platform=org.hibernate.dialect.H2Dialect
""",
    )


def _application_properties(name: str) -> FileSpec:
    return FileSpec(
        path="src/main/resources/application.properties",
        content=f"""spring.application.name={name}

spring.datasource.url=${{POSTGRES_URL:jdbc:postgresql://localhost:5432/{name}}}
spring.datasource.username=${{POSTGRES_USER:{name}}}
spring.datasource.password=${{POSTGRES_PASSWORD:{name}}}

spring.jpa.hibernate.ddl-auto=update
spring.jpa.open-in-view=false

management.endpoints.web.exposure.include=health,info
server.port={SPRING_PORT}
""",
    )
